import {escapeXML,objectBounds} from './suite-plan.js';
import {REVISION} from './revision-config.js';

export function revisionRoomTable(){
 const rows=[['Primary bath','11′ 1″ × 15′ 4″','Written A-102 dimensions; includes WC zone'],['Walk-in closet','13′ 1″ × approximately 11′ 2″','Traced clear faces, before cabinetry'],['Vanity','96″ × 20″','Plan symbol envelope; height and case details provisional'],['Shower','66″ × 54″','Plan symbol envelope; product / glass details provisional'],['Tub','66″ × 32″','Plan symbol envelope'],['Bedroom numbering','Main: Bedroom 2; basement: Bedrooms 3 and 4','Rev 1 room labels'],['Stairs','Top front / east; bottom back / west','Owner-confirmed direction; existing footprint retained'],['Garage entry','Top landing at door 9','Landing size and rise remain provisional']];
 return '<table><thead><tr><th>Element</th><th>Rev 1 basis</th><th>Source / scope</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+escapeXML(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
}
export function revisionNotes(){return '<h3>October 6 revision</h3><p>A-101 and A-102, Revision 1 dated October 6, 2026 (plot date September 22). This version uses the revised suite partitions and fixtures, basement storage walls and openings, garage-entry landing and room numbers. The earlier B.3 powder vanity and wider shower remain in the separate earlier-study design.</p><h3>Stairs and windows</h3><p>The front door is east (toward the bottom of the plan) and the back door is west (toward the top). The upper stair flight enters from the front-door side; the lower flight exits toward the back/game room. The right-hand stair wall remains intact. Treads and vertical rise remain schematic. The two B windows in the primary bath carry the drawing’s tempered-glass note; this model does not certify products.</p><h3>Whole-house review and furnishings</h3><p>North is toward sheet-right. The main family-room sofa faces a north-wall TV; six-seat dining is in the southwest corner. The stove follows the corner plan symbol. Laundry sink, corrected fixture positions, basement posts and an open shower entry are included. The dry bar has been removed. Furniture, finishes, TV size, hearth and flue appearance are a design study.</p><h3>Model scope</h3><p>Wall footprints were traced from the revised PDF and basement redline. Existing vaults are carried forward from the earlier section drawings. Furniture, lighting, cabinet construction and materials remain editable design choices. Neither the earlier 90-degree stair alternative nor its calculator changes this revision’s stair footprint.</p>';}
export function revisionComparisonSVG(original,revised,objects,originalObjects){
 const panels=[[original,originalObjects,'01 / ORIGINAL PLAN'],[revised,objects,'02 / OCTOBER 6 · REV 1']],out=[];
 out.push('<svg xmlns="http://www.w3.org/2000/svg" width="1180" height="1030" viewBox="0 0 1180 1030" role="img" aria-label="Original and October 6 revised primary suite"><rect width="1180" height="1030" fill="#faf9f5"/><g font-family="Arial" fill="#233b40"><text x="40" y="45" font-size="28">Primary suite · October 6 revised plan</text><text x="40" y="78" font-size="15">A-102 REVISION 1 · Dimensions follow the revised drawing; fixtures reflect current edits.</text>');
 for(const [i,[model,fixtures,label]] of panels.entries()){
  const left=i?650:65,X=x=>left+(x-58)*24,Y=z=>150+(z-17)*24;
  out.push(`<text x="${left}" y="137" font-size="17" font-weight="bold">${label}</text><defs><clipPath id="revclip${i}"><rect x="${left}" y="150" width="490" height="756"/></clipPath></defs><g clip-path="url(#revclip${i})"><rect x="${left}" y="150" width="490" height="756" fill="#eeeae1"/>`);
  for(const wall of model.walls)out.push(`<polygon points="${wall.map(([x,z])=>X(x)+','+Y(z)).join(' ')}" fill="#344e53"/>`);
  for(const o of fixtures){if(o.type==='suiteMirror')continue;const [x0,z0,x1,z1]=objectBounds(o);if(x1<58||z1<17||x0>78||z0>48.5)continue;out.push(`<rect x="${X(x0)}" y="${Y(z0)}" width="${(x1-x0)*24}" height="${(z1-z0)*24}" fill="${o.type==='wardrobe'?'#c9b291':'#d8e6e5'}" stroke="#627d7c"/><text x="${X(o.x)}" y="${Y(o.z)}" text-anchor="middle" font-size="9">${escapeXML(o.type==='suiteShower'?'SHOWER':o.type==='vanity'?'VANITY':o.type==='tub'?'TUB':o.type==='toilet'?'WC':'')}</text>`);}
  if(i)out.push(`<text x="${X(69)}" y="${Y(25)}" text-anchor="middle" font-size="17">WALK-IN CLOSET</text><text x="${X(68)}" y="${Y(36)}" text-anchor="middle" font-size="17">PRIMARY BATH</text><text x="${X(68)}" y="${Y(37.2)}" text-anchor="middle" font-size="13">11′ 1″ × 15′ 4″</text>`);
  out.push('</g>');
 }
 out.push('<text x="40" y="950" font-size="14">Original plan is retained for comparison. Rev 1 does not include the B.3 seated powder vanity.</text><text x="40" y="976" font-size="14">Model coordinates are in feet. Fixture products and vertical dimensions remain provisional.</text></g></svg>');return out.join('');
}
export function revisionReviewHTML(svg,table,notes,objects=[]){const fixtures=objects.filter(o=>o.id.startsWith('suite-')).map(o=>'<tr><td>'+escapeXML(o.name)+'</td><td>'+[o.w,o.d,o.h].map(v=>(v*12).toFixed(2)).join(' × ')+'</td><td>'+[o.x,o.z].map(v=>v.toFixed(3)).join(', ')+'</td><td>'+o.rotation+'°</td></tr>').join('');return `<!doctype html><html lang="en"><meta charset="utf-8"><title>${REVISION}</title><style>body{max-width:1180px;margin:30px auto;padding:20px;font:15px/1.6 Arial;color:#233b40}svg{width:100%;height:auto}table{border-collapse:collapse;width:100%}td,th{padding:9px;border-bottom:1px solid #bbc6c6;text-align:left}@media print{svg{break-after:page}}</style><h1>${REVISION}</h1>${svg}${table}${notes}<h2>Current fixture envelopes</h2><table><thead><tr><th>Fixture</th><th>W × D × H (in)</th><th>Center X / Z (ft)</th><th>Rotation</th></tr></thead><tbody>${fixtures}</tbody></table></html>`;}
